// Simulating the Random class structure
class Random {
 private:
  uint32_t seed_;

 public:
  explicit Random(uint32_t s) : seed_(s & 0x7fffffffu) {}

  uint32_t Next() {
    // Simple LCG implementation for testing
    seed_ = seed_ * 1103515245 + 12345;
    return (seed_ >> 16) & 0x7fff;
  }

  // Returns a uniformly distributed value in the range [0..n-1]
  // REQUIRES: n > 0
  uint32_t Uniform(int n) {
    return Next() % n;
  }
};

int main() {
  Random rnd(12345);

  // Test that Uniform returns values in [0, n-1]
  for (int i = 0; i < 100; i++) {
    uint32_t val = rnd.Uniform(10);
    if (val >= 10) {
      std::cout << "FAIL: value " << val << " out of range [0, 9]" << std::endl;
      return 1;
    }
  }

  std::cout << "PASS: All values in range [0, 9]" << std::endl;
  return 0;
}

