#include <cstdint>

class Random {
 private:
  uint32_t seed_;

 public:
  explicit Random(uint32_t s) : seed_(s & 0x7fffffffu) {}

  uint32_t Next() {
    seed_ = seed_ * 1103515245 + 12345;
    return (seed_ >> 16) & 0x7fff;
  }

  uint32_t Uniform(int n) {
    return Next() % n;
  }
};

int main() {
  Random rnd(12345);
  for (int i = 0; i < 100; i++) {
    uint32_t val = rnd.Uniform(10);
    if (val >= 10) return 1;
  }
  return 0;
}
